// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target, address caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(target != address(0) && target != address(c));
        vm.assume(amount <= address(c).balance);
        vm.deal(address(c), amount + 1 ether);
        vm.prank(c.owner());
        c.sendMoney(target, amount);
        vm.deal(caller, 0);
        vm.prank(caller);
        try c.withdrawAll() {
            assertTrue(caller == c.owner());
        } catch {
            assertTrue(caller != c.owner());
        }
    }
}
